<?php
declare(strict_types=1);
/** Bounded planner actions. No arbitrary code, SQL, publication, or permanent deletion. */
final class LifeCommands {
    public const ACTIONS=['task.save','task.move','task.schedule','task.archive','task.restore','task.complete','task.dependencies','checklist.toggle','goal.save','goal.archive','goal.restore','list.save','list.move','list.archive','list.restore','board.save','sprint.save','note.save','note.archive','note.restore','map.save','map.archive','map.connect','map.disconnect','routine.save','routine.toggle','review.save','quarter.review','memory.save','memory.remove','map.create'];
    public static function schema():array {return ['type'=>'OBJECT','required'=>['authorization','actions'],'properties'=>['authorization'=>['type'=>'STRING','description'=>'An exact quote of the CURRENT user instruction authorizing changes. Empty for discussion.'],'actions'=>['type'=>'ARRAY','items'=>['type'=>'OBJECT','required'=>['operation','arguments'],'properties'=>['operation'=>['type'=>'STRING','enum'=>self::ACTIONS],'arguments'=>['type'=>'STRING','description'=>'JSON object of arguments. Use exact existing IDs. For task.save/goal.save/note.save/map.save send only changed fields. Omit id to create.']]]]]];}
    public static function explicit(string $message,string $quote):bool {
        if($quote===''||!str_contains(mb_strtolower($message),mb_strtolower($quote)))return false;
        // Conservative: exploratory, conditional and negative instructions stay discussion.
        if(preg_match('/\b(don[’\x{0027}]?t|do not|never|not yet|without|instead of|if|could|would|should|maybe|might|thinking|consider|suggest|propose|example|imagine|hypothetical)\b/iu',$message))return false;
        return (bool)preg_match('/^(?:(?:okay|ok|yes|now|then|and|also|please|go ahead)[,\s.!:]*)*(?:(?:can|will) you\s+)?(?:please\s+)?(add|create|make|put|move|rename|change|update|edit|set|schedule|reschedule|link|archive|remove|restore|save|remember|forget|mark|complete|organize|turn|convert|connect|disconnect|undo)\b/iu',trim($quote));
    }
    public static function context(array $s):array {
        $index=[];foreach(['boards','lists','goals','tasks','notes','mapNodes','routines'] as $type){$rows=$s[$type]??[];$index[$type]=array_map(function($r){return array_intersect_key($r,array_flip(['id','title','name','archived','boardId','listId','goalId','parentId','type','period','completed','dueDate','schedule','group','kind','nextDate','priority','blocker','checklist']));},array_slice($rows,0,500));$index['counts'][$type]=count($rows);}
        $index['sprints']=$s['sprints']??[];$index['quarterReviews']=array_slice($s['quarterReviews']??[],-2,null,true);$index['week']=LifeStore::week();$index['date']=(new DateTimeImmutable('now',new DateTimeZone('Africa/Lagos')))->format('Y-m-d');return $index;
    }
    public static function execute(LifeStore $store,LifeAI $ai,int $version,int $boardVersion,string $message,array $plan,string $requestId):array {
        if(!self::explicit($message,LifeStore::text($plan['authorization']??'',6000)))throw new LifeError('Tell me explicitly what you want changed. Your planner has not been changed.',422);
        $actions=$plan['actions']??[];if(!is_array($actions)||count($actions)<1||count($actions)>20)throw new LifeError('Ask for between one and twenty changes at a time.',422);
        $db=$store->db;$db->beginTransaction();try{$r=$ai->read();foreach($r['state']['commands']??[] as $receipt)if($receipt['requestId']===$requestId){$db->commit();return $r+['board'=>$store->read(),'receipt'=>$receipt];}
        if($r['version']!==$version)throw new LifeError('This ramble changed. Try your command again.',409);$board=$store->read();if($board['version']!==$boardVersion)throw new LifeError('Your planner changed while I was thinking. No changes were made; try again.',409);$before=$board['state'];$memories=$r['state']['memories'];$state=$r['state'];$changed=[];
        foreach($actions as $a){$op=$a['operation']??'';if(!in_array($op,self::ACTIONS,true))throw new LifeError('That action is unavailable.',422);if($op==='memory.save'&&!preg_match('/\b(remember|memory)\b/iu',$plan['authorization']))throw new LifeError('Ask explicitly to remember that first.',422);if($op==='memory.remove'&&!preg_match('/\b(forget|memory)\b/iu',$plan['authorization']))throw new LifeError('Ask explicitly to forget that first.',422);$args=$a['arguments']??[];if(is_string($args))$args=json_decode($args,true,32,JSON_THROW_ON_ERROR);if(!is_array($args)||array_is_list($args)&&$args!==[])throw new LifeError('Invalid action arguments.',422);
          if(in_array($op,['memory.save','memory.remove'],true)){$saved=$ai->mutate($r['version'],$op,$args);$r=$saved;$state=$r['state'];$changed[]=$op;continue;}
          if($op==='map.create'){$nodes=$args['nodes']??[];if(!is_array($nodes)||count($nodes)<1||count($nodes)>30)throw new LifeError('A mind map needs one to thirty nodes.');$group=LifeStore::text($args['title']??'My thinking',60,true).' · '.substr(LifeStore::id(),0,6);$ids=[];foreach($nodes as $i=>$n){$board=$store->mutate($board['version'],'map.save',['title'=>$n['title']??'','kind'=>$n['kind']??'idea','group'=>$group,'x'=>80+($i%4)*400,'y'=>80+(int)floor($i/4)*260]);$ids[]=end($board['state']['mapNodes'])['id'];$parent=(int)($n['parent']??-1);if($parent>=0&&$parent<$i)$board=$store->mutate($board['version'],'map.connect',['from'=>$ids[$parent],'to'=>$ids[$i]]);}$changed[]='map.create';continue;}
          // Patch existing records rather than resetting omitted notes/checklists/goal fields.
          $type=match($op){'task.save'=>'tasks','goal.save'=>'goals','note.save'=>'notes','map.save'=>'mapNodes','routine.save'=>'routines',default=>null};
          if($type&&($args['id']??'')!==''){$old=null;foreach($board['state'][$type]??[] as $record)if($record['id']===$args['id'])$old=$record;if(!$old)throw new LifeError('That record is no longer available.',404);$args=array_merge($old,$args);}
          if($op==='sprint.save'){$week=$args['week']??LifeStore::week();$args=array_merge($board['state']['sprints'][$week]??['goal'=>'','taskIds'=>[]],$args,['week'=>$week]);}
          $board=$store->mutate($board['version'],$op,$args);$changed[]=$op;
        }
        $r=$ai->read();$state=$r['state'];$receipt=['id'=>LifeStore::id(),'requestId'=>$requestId,'operations'=>$changed,'afterVersion'=>$board['version'],'at'=>LifeStore::now(),'undone'=>false,'before'=>$before,'beforeMemories'=>$memories,'afterMemories'=>$state['memories']];$state['commands'][]=$receipt;$state['commands']=array_slice($state['commands'],-10);$updated=$ai->write($r['version'],$state);$db->commit();unset($receipt['before'],$receipt['beforeMemories']);return $updated+['board'=>$board,'receipt'=>$receipt];
        }catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
    }
    public static function undo(LifeStore $store,LifeAI $ai,int $version,string $id):array {
        $db=$store->db;$db->beginTransaction();try{$r=$ai->read();if($r['version']!==$version)throw new LifeError('Reload Ramble before undoing.',409);$s=$r['state'];$i=null;foreach($s['commands']??[] as $n=>$c)if($c['id']===$id)$i=$n;if($i===null||$s['commands'][$i]['undone'])throw new LifeError('This change cannot be undone.',409);$c=&$s['commands'][$i];$board=$store->read();if($board['version']!==$c['afterVersion'])throw new LifeError('Other work was saved after this command. Ask for a specific correction instead.',409);
        // Memory corrections must also survive undo of an older command.
        if(array_filter($c['operations'],fn($op)=>str_starts_with($op,'memory.'))){$after=$c['afterMemories']??null;if($after===null||$s['memories']!==$after)throw new LifeError('Memory changed after this command. Ask for a specific correction.',409);$s['memories']=$c['beforeMemories'];$s['memoryEpoch']=($s['memoryEpoch']??0)+1;foreach($s['conversations'] as &$chat)$chat['summary']='';unset($chat);}
        $q=$db->prepare('UPDATE life_board SET state=?,version=version+1,updated_at=? WHERE id=1 AND version=?');$q->execute([json_encode($c['before'],JSON_THROW_ON_ERROR),LifeStore::now(),$board['version']]);if($q->rowCount()!==1)throw new LifeError('Your planner changed before undo.',409);$c['undone']=true;unset($c);$updated=$ai->write($version,$s);$db->commit();return $updated+['board'=>$store->read()];}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
    }
}
